import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"路预测","description":"","frontmatter":{"title":"路预测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/way-prediction.md","filePath":"cs/way-prediction.md","lastUpdated":1789023840000}'),h={name:"cs/way-prediction.md"};function E(B,a,A,_,m,u){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="路预测" tabindex="-1">路预测 <a class="header-anchor" href="#路预测" aria-label="Permalink to &quot;路预测&quot;">​</a></h1><div class="epigraph"><p>组相联每拍读出所有路再比较标签，费能量；用 PC 或地址的低位猜哪一路，猜中则只启用那一路的数据阵列。</p><footer>—— 据 Powell et al.；Inoue 等对 way-predicting cache 的工作；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/cache-aliasing">上一课</a> 保证一组之内至多一份物理行。<a href="/cs/vipt-cache">VIPT</a> 仍要在命中路径上比较 \\(n\\) 路标签。L1 每拍都访问，功耗与 SRAM 读口成了限制频率的因素。本课不重做别名探测。缺口是<strong>路预测：先猜一路，错了再并行重试。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>8 路 L1D：标签小、数据宽，读 8 份 64B 再扔掉 7 份。真并行保证单周期命中，但能量按路数涨。许多访问的路随 PC 或最近历史稳定（循环扫同一数组走同一路模式）。缺口不是减路变成直接映射（冲突会回来），而是<strong>用小表预测 way 号，命中路径只激活一路</strong>。</p><p><span class="marginnote">猜错：多一拍变成「先错后全相联比较」，平均命中延迟略升。L1 对延迟敏感，所以预测必须很准，或仅用于指令 cache / L2。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路预测表：用 VA 或 PC 索引，存上次命中的 way。并行仍算标签（可只读预测路的标签+数据）。命中且 way 对：完成。way 错或标签不匹配：下一拍读其余路或全组，更新预测表。</p>',8)),(e(),l(p,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDX%5B%22%E7%B4%A2%E5%BC%95%20%2B%20%E8%B7%AF%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20ONE%5B%22%E5%8F%AA%E8%AF%BB%E9%A2%84%E6%B5%8B%E8%B7%AF%22%5D%0A%20%20ONE%20--%3E%7C%22%E6%A0%87%E7%AD%BE%E5%8C%B9%E9%85%8D%22%7C%20HIT%5B%22%E5%91%BD%E4%B8%AD%22%5D%0A%20%20ONE%20--%3E%7C%22%E4%B8%8D%E5%8C%B9%E9%85%8D%22%7C%20REST%5B%22%E5%85%B6%E4%BD%99%E8%B7%AF%E5%86%8D%E6%AF%94%22%5D%0A%20%20REST%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%E8%B7%AF%E9%A2%84%E6%B5%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>指令 cache 的路更可预测（顺序取指），L1I 常用；L1D 要更谨慎。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这是用平均延迟换平均能量，对 <a href="/cs/cpi-amdahl">CPI</a> 的影响是命中项从 1 拍变成 \\(1+p_{\\text{mis}}\\times\\) 惩罚。与分支预测不同：错路不会冲刷 ROB，只是 cache 多一拍。别名处理之后 way 号才稳定；着色失败会导致 way 表学乱。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把牺牲缓存当成路预测：牺牲缓存是直接映射冲突的旁路，下一课。也不把预测器做成 ISA 可见。伪相联（先读一路再读另一路）是路预测的近亲，可当作 way 数为 2 的特例。</p><p>后课默认：相联度的能量可以用猜路来砍。直接映射加一个全相联小缓冲，是另一条减冲突的路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>路预测少读数据阵列，猜错只加命中延迟、不冲刷。</li><li>L1I 通常比 L1D 更适合猜路。</li><li>直接映射的冲突用牺牲缓存补，是下一课。</li><li>出处：way-predicting cache 文献；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const P=o(h,[["render",E]]);export{D as __pageData,P as default};
